/**
 * Refresh the access token. The API client retries a 401 once after calling
 * this; with no hook wired there is nothing to retry with, so it reports
 * failure and the caller signs the user out.
 */
async function doRefresh(): Promise<boolean> {
  const refresh = await readRefresh();
  if (!refresh || !refreshHook) return false;
  const access = await refreshHook(refresh);
  if (!access) return false;
  await setSession(access);
  return true;
}

