/** The refresh currently in flight, shared by every caller. */
let refreshInFlight: Promise<boolean> | null = null;

/**
 * SINGLE-FLIGHT. A screen that fires five queries at once gets five 401s, and
 * each used to start its own refresh. Against a server that ROTATES refresh
 * tokens that is self-defeating: the first call consumes the token and returns
 * a new one, and the other four then present a token the server has already
 * retired — so they fail, the last write wins, and the user is signed out
 * mid-session for no reason. Everyone awaits the same promise, and the slot is
 * released in a finally so a rejection cannot wedge it permanently.
 */
export function refreshSession(): Promise<boolean> {
  refreshInFlight ??= doRefresh().finally(() => {
    refreshInFlight = null;
  });
  return refreshInFlight;
}

/** Launch ladder: is there anything to resume (live token or stored refresh)? */
export async function hasStoredSession(): Promise<boolean> {
  return isSignedIn() || (await readRefresh()) != null;
}

/**
 * Try to resume: a live access token wins; else mint one via refreshSession.
 */
export async function tryResumeSession(): Promise<boolean> {
  if (isSignedIn()) return true;
  if (!(await refreshSession())) return false;
  return true;
}
